ng? // Agency Owner CNIC Front Photo URL\n  cnicBackUrl          String? // Agency Owner CNIC Back Photo URL\n  latitude             Float? // Map location Latitude\n  longitude            Float? // Map location Longitude\n  storefrontPhoto      String? // Agency Storefront photo URL\n  ownerPhoto           String? // Agency Owner Passport/Identity photo URL\n  commercialLicenseDoc String? // Overseas Agency Tax Reg / Commercial License Document URL\n\n  users           User[]\n  listings        Listing[]\n  properties      Property[]\n  publicListings  PublicListing[]\n  clients         Client[]\n  ledgers         FinancialLedger[]\n  expenses        Expense[]\n  rentCollections RentCollection[]\n  agencyReviews   AgencyReview[]\n  deals           Deal[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Listing {\n  id          String  @id @default(uuid())\n  title       String\n  description String?\n  price       Float\n  address     String\n  latitude    Float?\n  longitude   Float?\n  area        Float?\n  roomCount   Int?\n  verifiedDoc Boolean @default(false)\n\n  agencyId String\n  agency   Agency @relation(fields: [agencyId], references: [id])\n\n  agentId String\n  agent   User   @relation(fields: [agentId], references: [id])\n\n  status ListingStatus @default(DRAFT)\n  deals  Deal[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n/// Comprehensive Property Model\nmodel Property {\n  id             String          @id @default(uuid())\n  title          String\n  description    String?\n  purpose        PropertyPurpose @default(FOR_SALE) // For Sale, For Rent, Lease\n  propertyType   String // House, Flat / Apartment, Commercial Plot, Office, etc.\n  category       String? // HOMES, PLOTS, COMMERCIAL, OTHER\n  price          Float // Sale Price or Monthly Rent/Price\n  address        String\n  city           String?\n  latitude       Float?\n  longitude      Float?\n  areaSqFt       Float?\n 